// Distinguishes a company-invite code from a per-email invitation UUID.
// UUIDs have 4 hyphens in fixed positions and are lowercase hex; company
// invite codes are letters/digits with a single dash: a short company prefix
// and a random suffix. Legacy codes look like "ABC-7K3X"; codes generated by
// create_company_invite() (Oct 2026) carry a 16-char suffix, e.g.
// "ABC-7K3XQ9MWR2TZHB4N".
export function looksLikeCompanyInviteCode(s) {
  if (!s || typeof s !== 'string') return false
  return /^[A-Z0-9]{1,6}-[A-Z0-9]{2,16}$/.test(s.toUpperCase())
}
